this[ "__gx_cache_file" ] = function( _manifestEntry ) {
    if (window.oprt && window.oprt.gameFiles) {

        var url = window.origin + "/" + _manifestEntry["name"];

        const urlParams = new URLSearchParams(window.location.search);
        const gameid = urlParams.get('game');
        const trackid = urlParams.get('track');
        const releaseid = urlParams.get('release');
        if (gameid!=null && trackid!=null && releaseid!=null) {


            url = window.location.origin + "/" + gameid + "/" + trackid + "/" + releaseid + "/" + _manifestEntry["name"];
        }

        console.log("__gx_cache_file for " + url);
      var request = new Request( url );
        let fileId = _manifestEntry["name"] + ":" + _manifestEntry["md5"];

        let response = window.oprt.gameFiles.fetchAndCache(fileId, g_CacheVersion, request).then((r) => {
            r.arrayBuffer().then(
                function () {
                    console.log("fetchAndCache complete for file:id " + fileId);
                    g_CachedFiles[_manifestEntry["name"]] = {
                        "name": _manifestEntry["name"],
                        "md5": _manifestEntry["md5"],
                        "fileId": fileId,
                        "version": g_CacheVersion
                    };
                }
            )



        });

    } // end if
    return Promise.resolve();
}


