this["__gx_check_cache"] = function (_fileId, _load_if_not_present) {



    var ret = g_CachedFiles[_fileId] != undefined;
    if (_load_if_not_present)
        console.log("__gx_check_cache for " + _fileId + " cached files " + JSON.stringify(g_CachedFiles) + " manifest files " + JSON.stringify(g_ManifestFiles));

  // if not cached but it is in the manifest then lets cache it
    if (!ret && (g_ManifestFiles[_fileId] != undefined) && _load_if_not_present) {

      this["__gx_cache_file"]( g_ManifestFiles[_fileId] );

  } // end if

  return ret;
} // end __gx_check_cache


